<script setup lang="ts">import { AlertCircle, Inbox, LoaderCircle, LockKeyhole } from 'lucide-vue-next';defineProps<{loading?:boolean;error?:string;empty?:boolean;forbidden?:boolean}>();defineEmits<{retry:[]}>()</script>
<template><div v-if="loading||error||empty||forbidden" class="resource-state"><LoaderCircle v-if="loading" class="spin"/><LockKeyhole v-else-if="forbidden"/><AlertCircle v-else-if="error"/><Inbox v-else/><strong>{{ loading?'数据加载中':forbidden?'暂无访问权限':error?'请求失败':'暂无数据' }}</strong><span>{{ forbidden?'当前账号缺少该功能权限':error||'当前筛选条件下没有记录' }}</span><button v-if="error" class="tech-button secondary" @click="$emit('retry')">重新加载</button></div><slot v-else/></template>
<style scoped>.resource-state{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;min-height:300px;color:#6385a3}.resource-state svg{color:#49aeef}.resource-state strong{color:#bcd2e4;font-size:13px}.resource-state span{font-size:10px}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}</style>

